@skipUnlessDBFeature("supports_over_clause")
class PrefetchLimitTests(TestDataMixin, TestCase):
    def test_slices(self):
        for relation in ("authors", "first_time_authors"):
            for ordering in (("name",), ()):
                authors = Author.objects.filter(name__in=["Anne", "Emily"]).order_by(
                    *ordering
                )
                for start, stop in ((0, 1), (1, 2), (3, None), (0, 0)):
                    with self.subTest(relation=relation, ordering=ordering, slice=(start, stop)):
                        sliced_authors = authors[start:stop]
                        with self.assertNumQueries(2 if start == stop else 3):
                            books = list(
                                Book.objects.prefetch_related(
                                    Prefetch(relation, authors),
                                    Prefetch(relation, sliced_authors, to_attr="sliced"),
                                )
                            )
                        self.assertEqual(sliced_authors.query.low_mark, start)
                        self.assertEqual(sliced_authors.query.high_mark, stop)
                        with self.assertNumQueries(0):
                            for book in books:
                                expected = list(getattr(book, relation).all())[start:stop]
                                self.assertEqual(book.sliced, expected)

    def test_without_to_attr(self):
        for relation in ("authors", "first_time_authors"):
            with self.subTest(relation=relation):
                authors = Author.objects.order_by("name")[1:2]
                with self.assertNumQueries(3):
                    books = list(
                        Book.objects.prefetch_related(
                            Prefetch(relation, Author.objects.order_by("name"), to_attr="all_authors"),
                            Prefetch(relation, authors),
                        )
                    )
                with self.assertNumQueries(0):
                    for book in books:
                        self.assertEqual(list(getattr(book, relation).all()), book.all_authors[1:2])
                self.assertEqual((authors.query.low_mark, authors.query.high_mark), (1, 2))

    def test_unsupported_backend(self):
        with mock.patch.object(connection.features, "supports_over_clause", False):
            for relation in ("authors", "first_time_authors"):
                with self.subTest(relation=relation):
                    with self.assertRaisesMessage(
                        NotSupportedError,
                        "Prefetching from a limited queryset is only supported on "
                        "backends that support window functions.",
                    ):
                        list(Book.objects.prefetch_related(Prefetch(
                            relation, Author.objects.all()[:1], to_attr="sliced"
                        )))

